<script setup>
import { computed, onMounted, onUnmounted, reactive, ref } from 'vue';
import { Plus, Search } from '@element-plus/icons-vue';
import { apiRequest } from '../../lib/api.js';
const rows=ref([]),cards=ref([]),search=ref(''),open=ref(false),active=ref(0),error=ref(''),notice=ref(''),loading=ref(false),saving=ref(false);
const form=reactive({id:'',name:'',description:'',steps:[]});
const actions=[['after_followed_follow_back','被关注后回关'],['after_followed_reply_text','被关注后文本回复'],['after_followed_reply_image','被关注后图片回复']],uploading=ref(false);
const filtered=computed(()=>rows.value.filter(row=>`${row.id} ${row.name}`.toLowerCase().includes(search.value.trim().toLowerCase())));
function newStep(){return{name:`步骤 ${form.steps.length+1}`,action:'after_followed_reply_text',failure:'stop',config:{message_text_list:'',random:false,cardid:'',imageId:'',name:'',preview:''}}}
function hydrate(step){const base=newStep(),old=step.config||{},config={...base.config,...old};let action=step.action;if(action==='random_reply_text'){action='after_followed_reply_text';config.random=true}if(!Array.isArray(old.message_text_list)&&typeof old.message_text==='string'&&old.message_text)config.message_text_list=old.message_text;else if(Array.isArray(old.message_text_list))config.message_text_list=old.message_text_list.join('\n');if(!['after_followed_follow_back','after_followed_reply_text','after_followed_reply_card','after_followed_reply_image'].includes(action))action='after_followed_reply_text';return{...base,...step,action,config}}
function reset(row=null){Object.assign(form,{id:row?.id||'',name:row?.name||'',description:row?.description||'',steps:row?.steps?.map(hydrate)||[]});if(!form.steps.length)form.steps.push(newStep());active.value=0;error.value='';open.value=true}
function config(step){const c=step.config;if(step.action==='after_followed_follow_back')return{};if(step.action==='after_followed_reply_text')return{message_text_list:String(c.message_text_list||'').split('\n').map(line=>line.trim()).filter(Boolean),random:Boolean(c.random)};if(step.action==='after_followed_reply_card')return{cardid:c.cardid};return{imageId:c.imageId,name:c.name||''}}
function stepError(step,index){const label=`步骤 ${index+1}`;if(step.action==='after_followed_reply_text'&&!String(step.config.message_text_list||'').split('\n').some(line=>line.trim()))return`${label}：请填写回复文本。`;if(step.action==='after_followed_reply_card'&&!step.config.cardid)return`${label}：请选择卡片。`;if(step.action==='after_followed_reply_image'&&!step.config.imageId)return`${label}：请上传图片。`;return''}
async function pickImage(event,step){const file=event.target.files?.[0];event.target.value='';if(!file)return;if(!/^image\/(jpeg|png|gif|webp)$/.test(file.type)){error.value='仅支持 JPG、PNG、GIF、WEBP 图片。';return}if(file.size>3*1024*1024){error.value='图片不能超过 3MB。';return}uploading.value=true;error.value='';try{const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let offset=0;offset<bytes.length;offset+=0x8000)binary+=String.fromCharCode(...bytes.subarray(offset,offset+0x8000));let width=0,height=0;try{const bitmap=await createImageBitmap(file);width=bitmap.width;height=bitmap.height;bitmap.close?.()}catch{/* 尺寸可选 */}const saved=await apiRequest('reply-rule-images',{method:'POST',body:{data:btoa(binary),name:file.name.slice(0,120),width,height},timeoutMs:30000});step.config.imageId=saved.id;step.config.name=saved.name;step.config.preview=URL.createObjectURL(file)}catch(cause){error.value=cause.message}finally{uploading.value=false}}
function add(){form.steps.push(newStep());active.value=form.steps.length-1}
function remove(index){form.steps.splice(index,1);active.value=Math.max(0,Math.min(active.value,form.steps.length-1));form.steps.forEach((step,i)=>{if(/^步骤 \d+$/.test(step.name))step.name=`步骤 ${i+1}`})}
async function load(){loading.value=true;try{[rows.value,cards.value]=await Promise.all([apiRequest('task-templates'),apiRequest('cards')])}catch(cause){notice.value=cause.message;rows.value=[];cards.value=[]}finally{loading.value=false}}
async function save(){if(!form.name.trim()||form.steps.some(step=>!step.name.trim())){error.value='请填写模板名称和步骤名称。';return}const problem=form.steps.map(stepError).find(Boolean);if(problem){error.value=problem;return}saving.value=true;error.value='';try{const steps=form.steps.map(step=>({name:step.name,action:step.action,failure:step.failure,config:config(step)}));await apiRequest(form.id?`task-templates/${form.id}`:'task-templates',{method:form.id?'PATCH':'POST',body:{name:form.name,description:form.description,steps}});const message=form.id?'任务模板已更新。':'任务模板已创建。';open.value=false;await load();notice.value=message}catch(cause){error.value=cause.message}finally{saving.value=false}}
async function removeTemplate(row){try{await apiRequest(`task-templates/${row.id}`,{method:'DELETE'});await load();notice.value='任务模板已删除。'}catch(cause){notice.value=cause.message}}
onMounted(()=>{window.addEventListener('douyinjuhe-session',load);load()});onUnmounted(()=>window.removeEventListener('douyinjuhe-session',load));
</script>
<template><section class="template-page"><div class="manager-toolbar"><el-input v-model="search" :prefix-icon="Search" placeholder="搜索 ID / 名称" clearable/><el-button type="primary" :icon="Plus" @click="reset()">新增模板</el-button></div><div class="panel"><el-alert v-if="notice" :title="notice" type="info" show-icon @close="notice=''"/><el-table v-loading="loading" :data="filtered" empty-text="暂无任务模板"><el-table-column prop="id" label="ID" min-width="230"/><el-table-column prop="name" label="名称" min-width="150"/><el-table-column label="步骤数" width="100"><template #default="{row}">{{row.steps.length}}</template></el-table-column><el-table-column label="来源" width="120"><template #default>手动创建</template></el-table-column><el-table-column label="更新时间" width="180"><template #default="{row}">{{new Date(row.updated).toLocaleString()}}</template></el-table-column><el-table-column label="操作" width="130"><template #default="{row}"><el-button link type="primary" @click="reset(row)">编辑</el-button><el-popconfirm title="确定删除这个模板？" @confirm="removeTemplate(row)"><template #reference><el-button link type="danger">删除</el-button></template></el-popconfirm></template></el-table-column></el-table></div>
<el-dialog v-model="open" :title="form.id?'编辑任务模板':'新增任务模板'" width="min(980px,96vw)" class="template-dialog"><el-form label-position="top"><el-form-item label="模板名称" required><el-input v-model="form.name"/></el-form-item><el-form-item label="模板说明"><el-input v-model="form.description" type="textarea" maxlength="255" show-word-limit/></el-form-item><div class="step-heading"><strong>模板步骤</strong><el-button :icon="Plus" @click="add">新增步骤</el-button></div><div class="steps"><nav><button type="button" v-for="(step,index) in form.steps" :key="index" :class="{active:active===index}" @click="active=index"><b>{{index+1}}</b>{{step.name}}</button></nav><section v-if="form.steps[active]" class="step-config"><div class="step-heading"><strong>步骤 {{active+1}} 配置</strong><el-button type="danger" link :disabled="form.steps.length===1" @click="remove(active)">删除此步骤</el-button></div><div class="grid"><el-form-item label="步骤名称" required><el-input v-model="form.steps[active].name"/></el-form-item><el-form-item label="动作类型"><el-select v-model="form.steps[active].action"><el-option v-for="item in actions" :key="item[0]" :value="item[0]" :label="item[1]"/></el-select></el-form-item><el-form-item label="失败策略"><el-select v-model="form.steps[active].failure"><el-option label="stop" value="stop"/><el-option label="continue" value="continue"/></el-select></el-form-item></div><template v-if="form.steps[active].action==='after_followed_reply_text'"><el-form-item label="回复文本"><el-input v-model="form.steps[active].config.message_text_list" type="textarea" :rows="5" placeholder="每行一条"/></el-form-item><el-form-item label="多条时随机发送一条"><el-switch v-model="form.steps[active].config.random"/></el-form-item><small>只填一条时直接发送；填多条并关闭随机时，会按顺序全部发送。</small></template><template v-else-if="form.steps[active].action==='after_followed_reply_card'"><el-form-item label="选择卡片"><el-select v-model="form.steps[active].config.cardid" placeholder="请选择卡片"><el-option v-for="card in cards" :key="card.id" :label="card.name" :value="card.id"/></el-select></el-form-item></template><template v-else-if="form.steps[active].action==='after_followed_follow_back'"><small>有用户关注当前账号后，自动回关该用户。无需额外配置，可与其他步骤组合（例如回关后再发一条文本）。</small></template><template v-else><el-form-item label="图片"><input type="file" accept="image/jpeg,image/png,image/gif,image/webp" :disabled="uploading" @change="pickImage($event,form.steps[active])"/></el-form-item><small v-if="uploading">上传中…</small><small v-else-if="form.steps[active].config.imageId">已选择：{{form.steps[active].config.name||'图片'}}</small><small v-else>支持 JPG、PNG、GIF、WEBP，不超过 3MB。</small><img v-if="form.steps[active].config.preview" :src="form.steps[active].config.preview" alt="图片预览" class="image-preview"/></template></section></div></el-form><el-alert v-if="error" :title="error" type="error" :closable="false"/><template #footer><el-button @click="open=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">{{form.id?'保存模板':'创建模板'}}</el-button></template></el-dialog></section></template>
<style scoped>.manager-toolbar{display:flex;justify-content:flex-end;gap:10px;margin-bottom:22px}.manager-toolbar .el-input{width:280px}.panel{background:#fff;border-radius:20px;padding:20px;min-height:calc(100vh - 235px)}.panel .el-alert{margin-bottom:14px}.panel :deep(.el-table__empty-block){min-height:390px}.step-heading{display:flex;align-items:center;justify-content:space-between;margin:12px 0}.steps{display:grid;grid-template-columns:190px minmax(0,1fr);gap:18px}.steps nav{display:flex;flex-direction:column;gap:8px}.steps nav button{border:1px solid #e4eaf3;background:#fff;border-radius:7px;padding:10px;text-align:left}.steps nav button.active{border-color:#409eff;background:#ecf5ff;color:#337ecc}.steps nav b{display:inline-grid;place-items:center;width:23px;height:23px;border-radius:50%;background:#edf2f8;margin-right:8px}.step-config{border:1px solid #e5ebf3;border-radius:8px;padding:14px}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px}.el-select{width:100%}.image-preview{max-width:240px;max-height:240px;border-radius:8px;border:1px solid #e5ebf3;margin-bottom:12px}small{display:block;color:#8c98aa;margin:8px 0 14px}@media(max-width:700px){.manager-toolbar .el-input{width:100%}.manager-toolbar{flex-wrap:wrap}.panel{padding:12px}.steps{grid-template-columns:1fr}.steps nav{flex-direction:row;overflow:auto}.grid{grid-template-columns:1fr}}</style>
